// 2025-1-26 21:14:10
// 黄绿细分
// Pinwheel-2-2
// https://tilings.math.uni-bielefeld.de/substitution/pinwheel-2-1/

#define C(a,b) ((a).x*(b).y-(a).y*(b).x)
#define P(no, n1, a, u) (C(a-no, n1-no)*C(u-no, n1-no)>0.)

void mainImage( out vec4 O, vec2 U)
{
        O = vec4(0);
        vec2 R = iResolution.xy,
             u = U / R.y, v;

        vec2 a, b, c, d ,e ,f ,g, na,nb,nc;

        float i,T, r = 12., s = 3., t = sqrt(r*r+s*s);

        a.x = r;  b.y = s;


        for(i=0.; i<6.; i++)
        {
                if(T<.5){
                        e = (a+c)*.5;
                        d = b + normalize(a-b)*length(b-c)*s/t;
                        f = (d+a)*.5;
                        g = (d+c)*.5;
                        if(P(c, d, b, u)){// 左小绿色
                                T = 1.;
                                na = c, nb = b, nc =d; /////////////////////
                        }else if(P(e,f, a, u)){ // 最右
                                na = a, nb = e, nc = f;
                        }else if(P(e,g, c, u)){ // 左下
                                na=e , nb=c, nc = g;
                        }else if(P(e,d, g,u)){ // 下中
                                na = e, nb =d, nc = g;
                        }else{// 上中
                                na = d, nb =e , nc = f;
                        }
                }else{
                        T=0.;
                }
                a=na, b=nb, c=nc;
        }

        float dist = abs(C(u-b, normalize(a-b)));
        dist = min(dist, abs(C(u-b, normalize(c-b))));
        dist = min(dist, abs(C(u-c, normalize(a-c))));
        dist *= pow(2.*t/r,i-1.);
        O = -vec4( smoothstep( r*.012, r*.00, dist) );
        if(T<.5) O.xy += .5;
        else     O.y  += .5;

}
